"""Demo: enumerate and pretty-print all bracketings of a product."""
from __future__ import annotations
from typing import Iterator, List


def enumerate_bracketings(factors: List[str]) -> Iterator[str]:
    """Yield the fully-parenthesized strings of the given ordered factors."""
    if len(factors) == 1:
        yield factors[0]
        return
    for i in range(1, len(factors)):
        for left in enumerate_bracketings(factors[:i]):
            for right in enumerate_bracketings(factors[i:]):
                yield f"({left}*{right})"


if __name__ == "__main__":
    for k in range(1, 6):
        factors = [chr(ord("a") + j) for j in range(k)]
        forms = list(enumerate_bracketings(factors))
        print(f"{k} factors: {len(forms)} bracketings")
        for f in forms:
            print("   ", f)

"""Demo: three independent computations of the Catalan census, cross-checked."""
from __future__ import annotations
from math import comb
from typing import List


def catalan_closed(n: int) -> int:
    """C_n = binom(2n, n) / (n + 1)."""
    return comb(2 * n, n) // (n + 1)


def catalan_segner(n: int) -> int:
    """C_n via the Segner convolution recurrence."""
    c: List[int] = [1]
    for m in range(n):
        c.append(sum(c[i] * c[m - i] for i in range(m + 1)))
    return c[n]


def catalan_bracketings(n: int) -> int:
    """C_n by direct enumeration of bracketings of n+1 factors."""
    def count(k: int) -> int:
        if k == 1:
            return 1
        return sum(count(i) * count(k - i) for i in range(1, k))
    return count(n + 1)


if __name__ == "__main__":
    for n in range(9):
        a, b, c = catalan_closed(n), catalan_segner(n), catalan_bracketings(n)
        assert a == b == c
        print(f"C_{n} = {a}")

"""Demo: strictification via right-nested normal forms (free monoid skeleton)."""
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional


@dataclass(frozen=True)
class Tree:
    label: Optional[str] = None
    left: Optional["Tree"] = None
    right: Optional["Tree"] = None

    def flatten(self) -> List[str]:
        if self.left is None and self.right is None:
            return [] if self.label is None else [self.label]
        assert self.left is not None and self.right is not None
        return self.left.flatten() + self.right.flatten()


def of_word(word: List[str]) -> Tree:
    """Canonical right-nested bracketing of a word."""
    if len(word) == 1:
        return Tree(label=word[0])
    return Tree(left=Tree(label=word[0]), right=of_word(word[1:]))


def normalize(t: Tree) -> Tree:
    """Every bracketing maps to the unique normal form of its word."""
    return of_word(t.flatten())


if __name__ == "__main__":
    # Two different bracketings of a b c d.
    a, b, c, d = (Tree(label=x) for x in "abcd")
    t1 = Tree(left=Tree(left=Tree(left=a, right=b), right=c), right=d)  # (((ab)c)d)
    t2 = Tree(left=a, right=Tree(left=b, right=Tree(left=c, right=d)))  # (a(b(cd)))
    print("t1 flattens to", t1.flatten())
    print("t2 flattens to", t2.flatten())
    print("same normal form:",
          normalize(t1).flatten() == normalize(t2).flatten())

