from __future__ import annotations
from typing import Iterator, List


def enumerate_bracketings(factors: List[str]) -> Iterator[str]:
    """Enumerate all bracketings (parse trees) of an ordered list of factors.

    Uses the Segner split: pick the outermost bracket, recurse on both halves.
    """
    if len(factors) == 1:
        yield factors[0]
        return
    for i in range(1, len(factors)):
        for left in enumerate_bracketings(factors[:i]):
            for right in enumerate_bracketings(factors[i:]):
                yield f"({left}*{right})"

