"""Visualization: draw all bracketings (binary trees) of four factors."""
import matplotlib.pyplot as plt
from dataclasses import dataclass
from typing import Iterator, List, Optional, Tuple


@dataclass
class T:
    label: Optional[str] = None
    left: Optional["T"] = None
    right: Optional["T"] = None


def gen(factors: List[str]) -> Iterator[T]:
    if len(factors) == 1:
        yield T(label=factors[0]); return
    for i in range(1, len(factors)):
        for l in gen(factors[:i]):
            for r in gen(factors[i:]):
                yield T(left=l, right=r)


def layout(t: T, x: float, y: float, dx: float,
           pts: List[Tuple[float, float, str]],
           edges: List[Tuple[float, float, float, float]]) -> None:
    if t.label is not None:
        pts.append((x, y, t.label)); return
    lx, rx = x - dx, x + dx
    edges.append((x, y, lx, y - 1)); edges.append((x, y, rx, y - 1))
    pts.append((x, y, ""))
    layout(t.left, lx, y - 1, dx / 2, pts, edges)
    layout(t.right, rx, y - 1, dx / 2, pts, edges)


trees = list(gen(list("abcd")))
fig, axes = plt.subplots(1, len(trees), figsize=(3 * len(trees), 3))
for ax, t in zip(axes, trees):
    pts: List = []; edges: List = []
    layout(t, 0, 0, 1.0, pts, edges)
    for (x0, y0, x1, y1) in edges:
        ax.plot([x0, x1], [y0, y1], color="#555")
    for (x, y, lab) in pts:
        ax.scatter([x], [y], s=120,
                   color="#27ae60" if lab else "#34495e", zorder=3)
        if lab:
            ax.text(x, y - 0.35, lab, ha="center", fontsize=10)
    ax.axis("off")
fig.suptitle("The 5 bracketings of a*b*c*d  (C_3 = 5)")
plt.tight_layout()
plt.savefig("bracketing_trees.png", dpi=150)
print("saved bracketing_trees.png")
